def select(records, tenant=None):
    chosen=[]
    seen=set()
    for row in records:
        if tenant is not None and row["tenant"]!=tenant:
            continue
        key=(row["tenant"], row["id"])
        if key in seen:
            continue
        seen.add(key)
        chosen.append(row)
    return chosen

import json
from pathlib import Path
from .validation import validate

def load(path):
    records=[]
    for number,line in enumerate(Path(path).read_text().splitlines(), 1):
        if not line.strip():
            continue
        try:
            row=json.loads(line)
        except json.JSONDecodeError:
            raise ValueError(f"line {number}: invalid JSON")
        validate(row, number)
        records.append(row)
    return records

import json

def render(records):
    return "".join(json.dumps(row,sort_keys=True)+"\n" for row in records)

